CREATE VIEW [purchase].[PurchaseRegister] AS SELECT i.PurchaseInvoiceId,i.InvoiceNumber,i.SupplierInvoiceNo,i.InvoiceDate,i.DueDate,i.SupplierId,s.SupplierCode,s.SupplierName,i.WarehouseId,w.WarehouseCode,i.Subtotal,i.DiscountAmount,i.TaxAmount,i.ExpenseAmount,i.RoundOff,i.GrandTotal,i.PaidAmount,purchase.PurchaseOutstanding(i.PurchaseInvoiceId)OutstandingAmount,i.Status FROM purchase.PurchaseInvoices i JOIN purchase.Suppliers s ON s.SupplierId=i.SupplierId JOIN inventory.Warehouses w ON w.WarehouseId=i.WarehouseId WHERE i.IsDeleted=0;
